mapper.select:
SELECT T.*, IF(sysProjectFunctionDefaultLabel is not null, 1, 0) sysProjectFunctionDefault FROM ( SELECT sp.*, sdi.sys_dict_item_name sysProjectDictItemLabel, sdi.sys_dict_item_code sysProjectDictItemCode, (SELECT group_concat(sdi.sys_dict_item_name) FROM sys_project_default spd INNER JOIN sys_dict_item sdi ON spd.sys_project_default_type = sdi.sys_dict_item_id WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultLabel, (SELECT group_concat(sdi.sys_dict_item_id) FROM sys_project_default spd INNER JOIN sys_dict_item sdi ON spd.sys_project_default_type = sdi.sys_dict_item_id WHERE spd.sys_project_id = sp.sys_project_id) sysProjectFunctionDefaultIds FROM sys_project sp LEFT JOIN sys_dict_item sdi ON sdi.sys_dict_item_id = sp.sys_project_vender
AND FIND_IN_SET( (SELECT sys_dict_item_id FROM sys_dict_item WHERE sys_dict_id = 6 AND sys_dict_item_code = #{request.sysProjectDictItemCode}) , sp.sys_project_function)
AND sys_project_id = #{request.sysProjectId}
AND sys_project_name LIKE CONCAT('%', #{request.sysProjectName}, '%')
AND sys_project_group = #{request.sysProjectGroup}
AND sys_project_status = #{request.sysProjectStatus}
AND sys_project_delete = #{request.sysProjectDelete}
AND sys_project_vender = #{request.sysProjectVender}
AND FIND_IN_SET(#{request.sysProjectFunction}, sys_project_function)
) T ORDER BY sysProjectFunctionDefault desc, sys_project_sort
